import pandas as pd
reviews = con.execute("SELECT business_ref, rating, date FROM review").df()
print(reviews.shape)
print(reviews.head())

# Try multiple date parses
def parse_date(s):
    for fmt in ("%B %d, %Y at %I:%M %p", "%d %b %Y, %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            return pd.to_datetime(s, format=fmt)
        except Exception:
            pass
    return pd.NaT

reviews['parsed'] = reviews['date'].apply(parse_date)
print('null parsed:', reviews['parsed'].isna().sum())
print(reviews[reviews['parsed'].isna()].head(10))
